func (fake *FakeHost) Touch(arg1 string, arg2 time.Time) error {
	fake.touchMutex.Lock()
	ret, specificReturn := fake.touchReturnsOnCall[len(fake.touchArgsForCall)]
	fake.touchArgsForCall = append(fake.touchArgsForCall, FakeHostTouchArgs{arg1, arg2})
	stub := fake.TouchStub
	fakeReturns := fake.touchReturns
	fake.recordInvocation("Touch", []interface{}{arg1, arg2})
	fake.touchMutex.Unlock()
	if stub != nil {
		return stub(arg1, arg2)
	}
	if specificReturn {
		return ret.result1
	}
	return fakeReturns.result1
}

func (fake *FakeHost) TouchCallCount() int {
	fake.touchMutex.RLock()
	defer fake.touchMutex.RUnlock()
	return len(fake.touchArgsForCall)
}

func (fake *FakeHost) TouchCalls(stub func(string, time.Time) error) {
	fake.touchMutex.Lock()
	defer fake.touchMutex.Unlock()
	fake.TouchStub = stub
}

